import { useState, useRef, useEffect } from 'react'
import { AnimatePresence, motion } from 'framer-motion'
import { Plus, Trash2, Download, Eye, EyeOff, ChevronDown, ChevronRight, Upload, Layers, Archive, ArchiveRestore, List, Pencil, Check } from 'lucide-react'
import { useUIStore } from '../../store'
import { useCustomPointLayerStore, type CustomPointLayer } from '../../store/customPointLayerStore'
import { AppWindow } from '../UI/AppWindow'

export function LayerManagerModal() {
  const layerManagerModalOpen = useUIStore(state => state.activeWindow === 'layerManager')
  const backWindow = useUIStore(state => state.backWindow)
  const openWindow = useUIStore(state => state.openWindow)
  const openLayerDashboard = useUIStore(state => state.openLayerDashboard)
  const { layers, removeLayer, toggleVisibility, toggleArchived, exportLayerAsGeoJSON, importLayerFromGeoJSON } = useCustomPointLayerStore()

  const [expandedLayerId, setExpandedLayerId] = useState<string | null>(null)
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null)
  const [importError, setImportError] = useState<string | null>(null)
  const [showArchived, setShowArchived] = useState(false)

  // Filter layers by archive status
  const activeLayers = layers.filter(l => !l.archived)
  const archivedLayers = layers.filter(l => l.archived)
  const displayedLayers = showArchived ? archivedLayers : activeLayers

  const handleDelete = (layerId: string) => {
    if (confirmDelete === layerId) {
      removeLayer(layerId)
      setConfirmDelete(null)
    } else {
      setConfirmDelete(layerId)
      // Auto-reset after 3 seconds
      setTimeout(() => setConfirmDelete(null), 3000)
    }
  }

  const handleExport = (layerId: string) => {
    exportLayerAsGeoJSON(layerId)
  }

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    try {
      const text = await file.text()
      const result = importLayerFromGeoJSON(text)

      if (!result.success) {
        setImportError(result.error || 'Import mislukt')
        setTimeout(() => setImportError(null), 3000)
      }
    } catch {
      setImportError('Kon bestand niet lezen')
      setTimeout(() => setImportError(null), 3000)
    }

    // Reset file input
    e.target.value = ''
  }

  const handleClose = () => {
    setExpandedLayerId(null)
    setConfirmDelete(null)
    setImportError(null)
    setShowArchived(false)
    backWindow()
  }

  const handleOpenDashboard = (layerId: string) => {
    openLayerDashboard(layerId)
  }

  const handleNewLayer = () => {
    setExpandedLayerId(null)
    setConfirmDelete(null)
    setImportError(null)
    setShowArchived(false)
    openWindow('createLayer', 'layerManager')
  }

  return (
    <AppWindow
      isOpen={layerManagerModalOpen}
      title="Mijn lagen beheren"
      icon={<Layers size={18} />}
      placement="modal"
      onClose={handleClose}
      onBack={handleClose}
      subHeader={
        <div className="flex">
              <button
                onClick={() => setShowArchived(false)}
                className={`flex-1 px-3 py-2 text-sm transition-colors border-0 outline-none ${
                  !showArchived
                    ? 'text-orange-600 border-b-2 border-orange-500 bg-orange-50/50'
                    : 'text-gray-500 hover:text-gray-700 hover:bg-gray-50'
                }`}
              >
                Actief ({activeLayers.length})
              </button>
              <button
                onClick={() => setShowArchived(true)}
                className={`flex-1 px-3 py-2 text-sm transition-colors border-0 outline-none flex items-center justify-center gap-1 ${
                  showArchived
                    ? 'text-orange-600 border-b-2 border-orange-500 bg-orange-50/50'
                    : 'text-gray-500 hover:text-gray-700 hover:bg-gray-50'
                }`}
              >
                <Archive size={14} />
                Archief ({archivedLayers.length})
              </button>
        </div>
      }
      footer={
        <div className="flex gap-3">
          <label className="detect-window-secondary-button flex-1 cursor-pointer">
            <Upload size={16} />
            <span>Importeren</span>
            <input
              type="file"
              accept=".geojson,.json"
              onChange={handleImport}
              className="hidden"
            />
          </label>
          <button onClick={handleNewLayer} className="detect-window-primary-button flex-1">
            <Plus size={16} />
            <span>Nieuwe laag</span>
          </button>
        </div>
      }
    >
            <div>
              {displayedLayers.length === 0 ? (
                <div className="p-8 text-center text-gray-500">
                  {showArchived ? (
                    <p style={{ fontSize: '1em' }}>Geen gearchiveerde lagen.</p>
                  ) : (
                    <>
                      <p className="mb-4" style={{ fontSize: '1em' }}>Je hebt nog geen eigen lagen.</p>
                      <button
                        onClick={handleNewLayer}
                        className="px-4 py-2 bg-orange-500 hover:bg-orange-600 text-white rounded-lg transition-colors border-0 outline-none"
                        style={{ fontSize: '1em' }}
                      >
                        <Plus size={16} className="inline mr-2" />
                        Nieuwe laag aanmaken
                      </button>
                    </>
                  )}
                </div>
              ) : (
                <div className="divide-y divide-gray-100">
                  {displayedLayers.map(layer => (
                    <LayerItem
                      key={layer.id}
                      layer={layer}
                      isExpanded={expandedLayerId === layer.id}
                      onToggleExpand={() => setExpandedLayerId(expandedLayerId === layer.id ? null : layer.id)}
                      onToggleVisibility={() => toggleVisibility(layer.id)}
                      onToggleArchived={() => toggleArchived(layer.id)}
                      onOpenDashboard={() => handleOpenDashboard(layer.id)}
                      onExport={() => handleExport(layer.id)}
                      onDelete={() => handleDelete(layer.id)}
                      confirmDelete={confirmDelete === layer.id}
                      onRename={(newName) => useCustomPointLayerStore.getState().updateLayer(layer.id, { name: newName })}
                      onChangeColor={(color) => useCustomPointLayerStore.getState().updateLayer(layer.id, { color })}
                    />
                  ))}
                </div>
              )}

              {/* Import error */}
              {importError && (
                <div className="mx-4 my-2 p-3 bg-red-50 text-red-700 text-sm rounded-lg">
                  {importError}
                </div>
              )}
            </div>
    </AppWindow>
  )
}

// Available colors for layers
const LAYER_COLORS = [
  '#ef4444', // red
  '#f97316', // orange
  '#eab308', // yellow
  '#22c55e', // green
  '#06b6d4', // cyan
  '#3b82f6', // blue
  '#8b5cf6', // violet
  '#ec4899', // pink
]

// Layer item component
function LayerItem({
  layer,
  isExpanded,
  onToggleExpand,
  onToggleVisibility,
  onToggleArchived,
  onOpenDashboard,
  onExport,
  onDelete,
  confirmDelete,
  onRename,
  onChangeColor
}: {
  layer: CustomPointLayer
  isExpanded: boolean
  onToggleExpand: () => void
  onToggleVisibility: () => void
  onToggleArchived: () => void
  onOpenDashboard: () => void
  onExport: () => void
  onDelete: () => void
  confirmDelete: boolean
  onRename: (newName: string) => void
  onChangeColor: (color: string) => void
}) {
  const [isEditing, setIsEditing] = useState(false)
  const [editName, setEditName] = useState(layer.name)
  const [showColorPicker, setShowColorPicker] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  // Focus input when editing starts
  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus()
      inputRef.current.select()
    }
  }, [isEditing])

  const handleStartEdit = () => {
    setEditName(layer.name)
    setIsEditing(true)
  }

  const handleSaveEdit = () => {
    const trimmed = editName.trim()
    if (trimmed && trimmed !== layer.name) {
      onRename(trimmed)
    }
    setIsEditing(false)
  }

  const handleCancelEdit = () => {
    setEditName(layer.name)
    setIsEditing(false)
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSaveEdit()
    } else if (e.key === 'Escape') {
      handleCancelEdit()
    }
  }

  // Calculate stats
  const completedCount = layer.points.filter(p => p.status === 'completed').length
  const totalCount = layer.points.length

  return (
    <div className="bg-white">
      {/* Layer header */}
      <div className="flex items-center gap-3 px-4 py-3">
        {/* Expand button */}
        <button
          onClick={onToggleExpand}
          className="p-1 text-gray-400 hover:text-gray-600 transition-colors border-0 outline-none bg-transparent"
        >
          {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
        </button>

        {/* Color dot - clickable */}
        <div className="relative">
          <button
            onClick={() => setShowColorPicker(!showColorPicker)}
            className="w-5 h-5 rounded-full flex-shrink-0 border-2 border-white shadow-sm hover:scale-110 transition-transform cursor-pointer"
            style={{ backgroundColor: layer.color }}
            title="Kleur wijzigen"
          />
          {/* Color picker dropdown */}
          {showColorPicker && (
            <div className="absolute top-7 left-0 z-50 bg-white rounded-lg shadow-lg p-2 flex flex-wrap gap-1 w-24">
              {LAYER_COLORS.map(color => (
                <button
                  key={color}
                  onClick={() => {
                    onChangeColor(color)
                    setShowColorPicker(false)
                  }}
                  className={`w-5 h-5 rounded-full border-2 hover:scale-110 transition-transform ${
                    color === layer.color ? 'border-gray-800' : 'border-white'
                  }`}
                  style={{ backgroundColor: color }}
                />
              ))}
            </div>
          )}
        </div>

        {/* Layer name and count - editable or clickable */}
        {isEditing ? (
          <div className="flex-1 min-w-0 flex items-center gap-2">
            <input
              ref={inputRef}
              type="text"
              value={editName}
              onChange={(e) => setEditName(e.target.value)}
              onKeyDown={handleKeyDown}
              onBlur={handleSaveEdit}
              className="flex-1 px-2 py-1 text-gray-800 font-medium bg-orange-50 rounded outline-none focus:ring-2 focus:ring-orange-400"
            />
            <button
              onClick={handleSaveEdit}
              className="p-1 text-green-600 hover:bg-green-50 rounded transition-colors border-0 outline-none"
              title="Opslaan"
            >
              <Check size={16} />
            </button>
          </div>
        ) : (
          <button
            onClick={onOpenDashboard}
            className="flex-1 min-w-0 text-left border-0 outline-none bg-transparent hover:bg-orange-50 rounded px-2 py-1 -ml-2 transition-colors"
            title="Bekijk dashboard"
          >
            <div className="font-medium text-gray-800 truncate hover:text-orange-600">{layer.name}</div>
            <div className="text-xs text-gray-500">
              {totalCount > 0 ? (
                <span className={completedCount === totalCount ? 'text-green-600' : ''}>
                  {completedCount}/{totalCount} voltooid
                </span>
              ) : (
                'Geen punten'
              )}
            </div>
          </button>
        )}

        {/* Edit name button */}
        {!isEditing && (
          <button
            onClick={handleStartEdit}
            className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded transition-colors border-0 outline-none"
            title="Naam bewerken"
          >
            <Pencil size={16} />
          </button>
        )}

        {/* Dashboard button */}
        <button
          onClick={onOpenDashboard}
          className="p-2 text-orange-400 hover:text-orange-600 hover:bg-orange-50 rounded transition-colors border-0 outline-none"
          title="Open dashboard"
        >
          <List size={18} />
        </button>

        {/* Visibility toggle - only for non-archived */}
        {!layer.archived && (
          <button
            onClick={onToggleVisibility}
            className={`p-2 rounded transition-colors border-0 outline-none ${
              layer.visible ? 'text-blue-500 hover:bg-blue-50' : 'text-gray-400 hover:bg-gray-100'
            }`}
            title={layer.visible ? 'Verbergen' : 'Tonen'}
          >
            {layer.visible ? <Eye size={18} /> : <EyeOff size={18} />}
          </button>
        )}

        {/* Archive/Unarchive */}
        <button
          onClick={onToggleArchived}
          className={`p-2 rounded transition-colors border-0 outline-none ${
            layer.archived
              ? 'text-green-500 hover:text-green-600 hover:bg-green-50'
              : 'text-gray-400 hover:text-amber-600 hover:bg-amber-50'
          }`}
          title={layer.archived ? 'Herstellen' : 'Archiveren'}
        >
          {layer.archived ? <ArchiveRestore size={18} /> : <Archive size={18} />}
        </button>

        {/* Export */}
        <button
          onClick={onExport}
          className="p-2 text-gray-400 hover:text-green-600 hover:bg-green-50 rounded transition-colors border-0 outline-none"
          title="Exporteren als GeoJSON"
        >
          <Download size={18} />
        </button>

        {/* Delete */}
        <button
          onClick={onDelete}
          className={`p-2 rounded transition-colors border-0 outline-none ${
            confirmDelete
              ? 'text-white bg-red-500 hover:bg-red-600'
              : 'text-gray-400 hover:text-red-600 hover:bg-red-50'
          }`}
          title={confirmDelete ? 'Klik nogmaals om te verwijderen' : 'Verwijderen'}
        >
          <Trash2 size={18} />
        </button>
      </div>

      {/* Expanded content */}
      <AnimatePresence>
        {isExpanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="overflow-hidden"
          >
            <div className="px-4 pb-3 pl-12 space-y-2">
              {/* Categories */}
              {layer.categories.length > 0 && (
                <div className="flex flex-wrap gap-1">
                  {layer.categories.map(cat => (
                    <span
                      key={cat}
                      className="px-2 py-0.5 bg-gray-100 text-gray-600 text-xs rounded-full"
                    >
                      {cat}
                    </span>
                  ))}
                </div>
              )}

              {/* Points preview with status */}
              {layer.points.length > 0 && (
                <div className="text-xs text-gray-500 space-y-1 max-h-32 overflow-y-auto">
                  {layer.points.slice(0, 5).map(point => (
                    <div key={point.id} className="flex items-center gap-2">
                      <span className={`font-medium ${
                        point.status === 'completed' ? 'text-green-600 line-through' :
                        point.status === 'skipped' ? 'text-gray-400 line-through' :
                        'text-gray-700'
                      }`}>{point.name}</span>
                    </div>
                  ))}
                  {layer.points.length > 5 && (
                    <div className="text-gray-400">
                      ...en {layer.points.length - 5} meer
                    </div>
                  )}
                </div>
              )}

              {/* Created date */}
              <div className="text-xs text-gray-400">
                Aangemaakt: {new Date(layer.createdAt).toLocaleDateString('nl-NL')}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}
